@startuml

class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + Number : string
}

class Bed {
  + BedNumber : string
}

class Category {
  + Price : double
}

class StayType {
  + Name : string
}

class RestHome {
  + Name : string
}

class RestNursingHome {
  + Name : string
}

class ServiceFlat {
  + Name : string
}

class Inhabitant {
  + Name : string
  + IdentificationData : string
}

class Registration {
  + RegistrationDate : date
}

class Assessment {
  + Needs : string
}

class WaitingList {
  + Position : int
}

class Proposal {
  + Status : string
}

class Invoice {
  + Amount : double
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

class PaymentEvent {
  + Amount : double
  + Date : date
}

Home "1" *-- "*" Department
Department "1" *-- "*" Room
Room "1" *-- "*" Bed
Bed "1" -- "1" Category
Category "1" -- "1" StayType

StayType <|-- RestHome
StayType <|-- RestNursingHome
StayType <|-- ServiceFlat

Inhabitant "1" -- "*" Stay
Stay "1" -- "1" StayType
Stay "1" -- "1" Bed

Inhabitant "1" -- "1" Registration
Registration "1" -- "1" Assessment
Assessment "1" -- "1" StayType

StayType "1" -- "*" WaitingList
WaitingList "*" -- "1" Inhabitant

Proposal "1" -- "1" Inhabitant
Proposal "1" -- "1" Bed
Proposal "1" -- "1" StayType

Stay "1" -- "*" Invoice
Invoice "1" -- "0..1" CreditNote
PaymentEvent "1" -- "1" Invoice

@enduml

